var url=source.getKey();

var html = java.ajax(url);

token = org.jsoup.Jsoup.parse(html)
.select('input[name=_token]')
.attr('value');

url+"/search,"+JSON.stringify({
  "body": `_token=${token}&keyword=${key}&searchtype=articlename`,
  "method": "post"
})

